import { DialogsService } from "../providers/uikit.dialogs";
import { ChangeTracker } from "../changeTracker";

declare var language : any;

export class NetCityModalController {
	/*@ngInject*/
	constructor(protected $scope, protected $uibModalInstance, protected changeTracker: ChangeTracker, protected $dialogs: DialogsService){
		$scope.$on("modal.closing", (event, reason) => {
			var message = language.Generic.Common.kDataWereChanged;
			let reasons = ["backdrop click", "cancel", "escape key press"];
			let modalCtx = this.modalCtx;
			
			var changed = changeTracker.isDataChanged(modalCtx);

			if ($.inArray(reason, reasons) >= 0 && changed) {
				event.preventDefault();
				$dialogs.confirm(message)
					.then(() => {
						changeTracker.clearDataChanges(modalCtx);
						$uibModalInstance.close();
					});
			};
		});
	}

	get modalCtx(){
		return $("div.modal.fade");
	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel");
	}
}


