const module = angular.module("irtech.netcity.admin.schools",
	[
		"ngRoute", "ngSanitize",
		"ngMessages", "angular-md5", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./list/SchoolsListCtrl.coffee");
require("./edit/EditSchoolCtrl.coffee");
import { AdminListCtrl } from "./adminllist/AdminListCtrl.js";
require("./registry/orgsRegistryCtrl.js");

require("webroot/vendor/components/angular-md5/angular-md5.min.js");
require("webroot/vendor/pages/js/browseSchoolInfoAccessJournal.js");

let registryTemplate = "/static/dist/app/global/templates/registry.html";

module
	.controller("AdminListCtrl", AdminListCtrl)
	.config(($routeProvider, $locationProvider) => {

		$routeProvider
			.when("/registry/", {
				templateUrl: registryTemplate,
				controller: "OrgsRegistryCtrl"
			})
			.otherwise({
				redirectTo: "/",
				templateUrl: "/static/dist/app/admin/schools/list/template.html",
				controller: "SchoolsListCtrl"
			});

		$locationProvider.hashPrefix("");
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});



