import { NetCityModalController } from "approot/global/controllers/netcityModalCtrl";
//import * as changePasswordCtrl from "webroot/static/src/pages/users/js/changePassword.coffee";
const changePasswordCtrl = require("webroot/static/src/pages/users/js/changePassword.coffee");

export class AdminListCtrl extends NetCityModalController {
	/*@ngInject*/
	constructor($scope, $http, $uibModalInstance, changeTracker, $dialogs, language, school) {
		super($scope, $uibModalInstance, changeTracker, $dialogs);

		this.$http = $http;
		this.school = school;
		this.header = "Администрирование образовательной организации";
		this.language = language;
		this.admins = [];
		this.ready = false;

		this.changePassCtrl = new changePasswordCtrl({});

		this.$http.get(`/webapi/schools/${school.id}/admins`)
			.then((response) => {
				this.ready = true
				this.admins = response.data
			})
				
	}

	changePassword(userId){
		this.changePassCtrl.changePassword(userId);
	}
}



