"use strict";

require("approot/global/controllers/registryCtrl.js");

angular
	.module("irtech.netcity.admin.schools")
	.controller("OrgsRegistryCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, $longWork) => {

		$scope.$parent.page = {
			title: "Образовательные организации"
		};

		const dateDecorator = { type: "map", map: (date) => dateUtils.date2str(new Date(date)) };
		const addBtnGroup = {
			title: language.Generic.Buttons.kAdd,
			icon: "glyphicon glyphicon-plus-sign",
			buttons: [
				{ title: "Добавить новую образовательную организацию", action: () => $scope.add() },
				{ title: "Импорт образовательных организаций", action: () => $scope.import() }
			]
		};

		$scope.registry = {
			url:  "/webapi/admin/organizations/registry",
			filtersUrl: "/webapi/admin/organizations/registry/filter",
			fieldDecorators: {
				"foundDate": dateDecorator,
				"name": { type: "link", action: (school) => $scope.edit(school) },
			},
			buttons: [],
			buttonGroups: [addBtnGroup]
		};

		$scope.registry.buttons.push({
			title : "Сведения об ОО",
			icon: "glyphicon glyphicon-info-sign",
			selectionMode: "Single",
			action: () => {
				$scope.edit();
			}
		});

		$scope.registry.buttons.push({
			title : "Администрирование ОО",
			icon: "glyphicon glyphicon-wrench",
			selectionMode: "Single",
			action: () => {
				$scope.admin();
			}
		});
		
		$scope.registry.buttons.push({
			title : "Удалить",
			icon: "glyphicon glyphicon-trash",
			selectionMode: "Single",
			action: () => {
				$scope.delete();
			}
		});

		$scope.admin = () => {
			const school = $scope.selection.selected[0];

			var modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/admin/schools/adminllist/template.html",
				controller: "AdminListCtrl",
				controllerAs: "ctrl",
				resolve: {
					school: () => school
				}
			});
		};

		$scope.add = () => {
			const fpValues = $scope.filterInfo.filterPanel.getValues();
			const fpTexts = $scope.filterInfo.filterPanel.getTexts();

			var cityId = parseInt(fpValues.city || -1);

			if (!cityId || cityId <= 0) {
				$.show.message("Выберите населенный пункт в фильтре");
				return;
			}

			const city = { id: cityId, name: fpTexts.city };

			var modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/admin/schools/edit/template.html",
				controller: "EditSchoolCtrl",
				size: "lg",
				resolve: {
					model: () => {
						return {
							school: null,
							city: city
						};
					}
				}
			});
			modalInstance.rendered.then(() => { dateInput.initDateInputs(); });
			modalInstance.result.then((createdSchool) => {
				$scope.load();
			});
		};

		$scope.edit = (school) => {
			const fpValues = $scope.filterInfo.filterPanel.getValues();
			const fpTexts = $scope.filterInfo.filterPanel.getTexts();

			school = school || $scope.selection.selected[0];
			const city = { id: fpValues.city, name: fpTexts.city };

			var modalInstance = $uibModal.open({
				templateUrl: "/static/dist/app/admin/schools/edit/template.html",
				controller: "EditSchoolCtrl",
				size: "lg",
				resolve: {
					model: () => {
						return {
							school: school,
							city: city
						};
					}
				}
			});
			modalInstance.rendered.then(() => { dateInput.initDateInputs(); });

			modalInstance.result.then((editedSchool) => {
				$scope.load();
			});
		};

		$scope.import = () => {
			const fpValues = $scope.filterInfo.filterPanel.getValues();
			var cityId = parseInt(fpValues.city || -1);
			var districtId = -1;

			if (!cityId || cityId <= 0) {
				$.show.message("Для выполнения импорта необходимо выбрать в фильрте муниципальный район и населенный пункт");
				return;
			}

			$http.get("/static/dist/app/admin/schools/list/import.html")
				.then((response) => {
					var template = response.data;

					$.show.fileDialog({
						title: language.Generic.Buttons.kImportOU,
						isAjax: true,
						submitParams: {
							cityId: cityId,
							districtId: districtId
						},
						fileExts: ['.xls'],
						url: "/asp/Administration/SchoolsImport.asp",

						handlerAjaxSuccess: (response) => {
							if (response.IsError) {
								$.show.error(response.data.message);
								return;
							}

							var model = {
								data: response.data,
								language: language,
								showDistricts: _.some(response.data.schoolList, (school) => school.DistrictName && school.DistrictName.length),
								showProvinces: _.some(response.data.schoolList, (school) => school.ProvinceName && school.ProvinceName.length),
								showComments: _.some(response.data.schoolList, (school) => school.Comment && school.Comment.length),
								showEOForm: _.some(response.data.schoolList, (school) => school.FormName && school.FormName.length)
							};
							var importUnavailable = !_.some(response.data.schoolList, (school) => school.CanImport);
							var source = template.replace(/(?:\r\n|\r|\n)/g, '');
							template = Handlebars.compile(source);
							var html = template(model);
							var buttons = [
								{
									label: language.Generic.Import.kBeginImport,
									cssClass: "btn-primary",
									action: (dialog) => {
										var selectedSchools = $("input[name='incEO']:checkbox:checked");
										if (selectedSchools.length === 0) {
											alert(language.Generic.ServAdmin.kMustSelectEO);
											return;
										}
										var data = {
											incEO: []
										};
										selectedSchools.each(() => data.incEO.push(this.value));

										jsSubmit({
											data: data,
											action: "/asp/Administration/SchoolsImportSave.asp",
											showProcessing: true
										}).then((response) => {
											dialog.close();
											$scope.reloadSchools();
											model = response.data.result;

											$http.get("/static/dist/app/admin/schools/list/import-completed.html")
												.then((response) => {
														template = response.data;
														source = template.replace(/(?:\r\n|\r|\n)/g, '');
														template = Handlebars.compile(source);
														html = template({
															model: model,
															language: language
														});

														$.show.dialog({
															title: language.Generic.Import.kTitleImportEO,
															size: BootstrapDialog.SIZE_WIDE,
															message: html,
															buttons: [
																{
																	label: language.Generic.Calendar.kClose,
																	action: function(dialog) {
																		return dialog.close();
																	}
																}
															]
														});
													});
										});
									}
								}, {
									label: language.Generic.Common.kCheckAll,
									action: (dialog) => {
										$('input[name="incEO"]:enabled:checkbox', document.MainForm).prop('checked', true);
									}
								}, {
									label: language.Generic.Common.kUnCheckAll,
									action: (dialog) => {
										$('input[name="incEO"]:enabled:checkbox', document.MainForm).prop('checked', false);
									}
								}
							];
							if (importUnavailable) {
								buttons = [];
							}

							$.show.dialog({
								title: language.Generic.Import.kTitleImportEO,
								size: BootstrapDialog.SIZE_WIDE,
								message: html,
								buttons: buttons
							});
						}
					});
				});
		};

		$scope.delete = () => {
			const school = $scope.selection.selected[0];

			$longWork.execute($http.get(`/webapi/schools/${school.id}/canDelete`))
				.then((response) => {
					if (!response.data) {
						alert(language.Generic.ServAdmin.kUnknownError);
						return null;
					}
					if (response.data.isWorkInSchool) {
						alert(response.data.message);
						return null;
					}

					var confirms = [];
					if (response.data.isCommonDataEnter) {
						confirms.push(
							$.show.getConfirmation(language.Generic.ServAdmin.kAreYouSureToDelSchool_DataEnter));
						confirms.push($.show.getConfirmation(language.Generic.ServAdmin.kAreYouSureToDelSchool2));
						confirms.push($.show.getConfirmation(language.Generic.ServAdmin.kAreYouSureToDelSchool3));
					} else {
						confirms.push($.show.getConfirmation(language.Generic.ServAdmin.kAreYouSureToDelSchool));
						confirms.push($.show.getConfirmation(language.Generic.ServAdmin.kAreYouSureToDelSchool2));
					}
					return extDeferred.when(confirms);
				})
				.then(() => {
					return $longWork.execute($http["delete"](`/webapi/schools/${school.id}`));
				})
				.then(() => {
					alert("Образовательная организация успешно удалена");
					$scope.load();
				},
				(response) => {
					$.show.error(response.data.message || response.data.details);
				});
		};

		$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts });
	});



